CREATE TABLE IF NOT EXISTS auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_session (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, token text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, ip_address text, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_session_user_idx ON auth_session(user_id);
CREATE TABLE IF NOT EXISTS auth_account (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, account_id text NOT NULL, provider_id text NOT NULL, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_account_user_idx ON auth_account(user_id);
CREATE TABLE IF NOT EXISTS auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS business (id text PRIMARY KEY, name text NOT NULL, accent text NOT NULL DEFAULT '#2f6b51', initials text NOT NULL DEFAULT 'B', active boolean NOT NULL DEFAULT true, expires_at timestamptz NOT NULL, allowance integer NOT NULL DEFAULT 100 CHECK(allowance >= 0), used integer NOT NULL DEFAULT 0 CHECK(used >= 0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved >= 0));
CREATE TABLE IF NOT EXISTS membership (user_id text NOT NULL REFERENCES auth_user(id), business_id text NOT NULL REFERENCES business(id), PRIMARY KEY(user_id,business_id));
CREATE TABLE IF NOT EXISTS platform_admin (user_id text PRIMARY KEY REFERENCES auth_user(id));
CREATE TABLE IF NOT EXISTS location (id text PRIMARY KEY, business_id text NOT NULL REFERENCES business(id), slug text NOT NULL UNIQUE, qr_code text NOT NULL UNIQUE, name text NOT NULL, address text NOT NULL, google_url text, active boolean NOT NULL DEFAULT true, UNIQUE(business_id,id));
CREATE TABLE IF NOT EXISTS guest_session (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, location_id text NOT NULL REFERENCES location(id), expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0));
CREATE TABLE IF NOT EXISTS generation (id text PRIMARY KEY, guest_id text NOT NULL REFERENCES guest_session(id), business_id text NOT NULL REFERENCES business(id), location_id text NOT NULL, request_key text NOT NULL, input_hash text NOT NULL, state text NOT NULL CHECK(state IN ('pending','succeeded','failed')), output_encrypted text, output_locale text NOT NULL, platform text NOT NULL, provider text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), deadline_at timestamptz NOT NULL, error_code text, UNIQUE(guest_id,request_key), FOREIGN KEY(business_id,location_id) REFERENCES location(business_id,id));
CREATE INDEX IF NOT EXISTS generation_business_idx ON generation(business_id,created_at);
CREATE INDEX IF NOT EXISTS generation_pending_idx ON generation(deadline_at) WHERE state='pending';
CREATE TABLE IF NOT EXISTS ai_daily_budget (day date PRIMARY KEY, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0));
CREATE TABLE IF NOT EXISTS audit_event (id text PRIMARY KEY, actor_id text NOT NULL REFERENCES auth_user(id), business_id text NOT NULL REFERENCES business(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS review_app_meta (id text PRIMARY KEY);
INSERT INTO review_app_meta(id) VALUES('independent-review-mvp-v1') ON CONFLICT DO NOTHING;
